<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { api, APIError } from '../api'
import { formatDate, formatNumber, locale, t } from '../i18n'
import { useWorkspaceStore } from '../stores/workspace'
import { Button } from '../components/ui/button'
import { ScrollArea } from '../components/ui/scroll-area'
import Icon from '../components/Icon.vue'
import DatePicker from '../components/DatePicker.vue'
import AppSelect from '../components/AppSelect.vue'
import WorkloadTrends from '../components/WorkloadTrends.vue'
import { currentWorkloadMonth, moveWorkloadMonth, validWorkloadMonth, workloadRoleNames, workloadRows, type WorkloadDimension, type WorkloadReport, type WorkloadSort } from '../workload'

const workspace=useWorkspaceStore(),{identityConflict}=storeToRefs(workspace)
const trendRefresh=ref(0),monthValid=ref(true)
const month=ref(currentWorkloadMonth()),report=ref<WorkloadReport|null>(null),loading=ref(false),error=ref(''),forbidden=ref(false),dimension=ref<WorkloadDimension>('people'),search=ref(''),department=ref('*'),role=ref(''),sort=ref<WorkloadSort>('weight'),descending=ref(true)
let sequence=0,disposed=false,controller:AbortController|undefined
const rows=computed(()=>report.value?workloadRows(report.value,dimension.value,{search:search.value,department:department.value,role:role.value,sort:sort.value,descending:descending.value,locale:locale.value,translate:t}):[])
const dimensions: {key:WorkloadDimension;name:string}[]=[{key:'people',name:'人员贡献'},{key:'departments',name:'部门汇总'},{key:'roles',name:'职能汇总'}]
const metrics: {key:Exclude<WorkloadSort,'name'>;name:string}[]=[{key:'weight',name:'已填工作权重'},{key:'requirementCount',name:'关联需求'},{key:'shippedRequirementCount',name:'已上线需求'},{key:'defectCount',name:'迭代缺陷'}]
const hasGaps=computed(()=>!!report.value&&(report.value.unassignedWeight>0||report.value.unassignedRequirementCount>0||report.value.unassignedDefectCount>0||report.value.unestimatedRequirementCount>0||report.value.ambiguousSprintItemCount>0))
const departmentOptions=computed(()=>[
  {value:'*',label:t('所有部门')},
  ...(report.value?.departments||[]).map(item=>({value:item.id,label:item.name||t('未分配部门')})),
])
const roleOptions=computed(()=>[
  {value:'',label:t('所有职能')},
  ...(report.value?.roles||[]).map(item=>({value:item.key,label:t(workloadRoleNames[item.key]||item.key)})),
])
const formatWeight=(value:number)=>formatNumber(value,{maximumFractionDigits:6})
function invalidate(){sequence++;controller?.abort();report.value=null;loading.value=false;error.value='';forbidden.value=false}
function setMonthValidity(valid:boolean){monthValid.value=valid;if(!valid){sequence++;controller?.abort();loading.value=false}}
async function load(){
  if(disposed||identityConflict.value||!workspace.currentUser||!monthValid.value)return
  const request=++sequence,selectedMonth=month.value,user=workspace.currentUser.id,tenant=workspace.session?.tenant.id
  controller?.abort();controller=new AbortController();error.value='';forbidden.value=false
  if(report.value?.month!==selectedMonth)report.value=null
  if(!validWorkloadMonth(selectedMonth)){loading.value=false;error.value='月份必须为有效的 YYYY-MM 格式';return}
  loading.value=true
  const current=()=>!disposed&&request===sequence&&!identityConflict.value&&workspace.currentUser?.id===user&&workspace.session?.tenant.id===tenant&&month.value===selectedMonth
  try{
    const data=await api<WorkloadReport>('/reports/workload?month='+encodeURIComponent(selectedMonth),{signal:controller.signal})
    if(!current())return
    if(data.month!==selectedMonth||data.scope.tenantId!==tenant||data.scope.type!=='organization')throw new Error('统计上下文校验失败，请重试')
    report.value=data;trendRefresh.value++
  }catch(cause){if(current()){forbidden.value=cause instanceof APIError&&[401,403].includes(cause.status);if(forbidden.value)report.value=null;error.value=cause instanceof Error?cause.message:t('月度工作量暂时无法读取，请稍后重试')}}
  finally{if(current())loading.value=false}
}
function changeSort(key:WorkloadSort){if(sort.value===key)descending.value=!descending.value;else{sort.value=key;descending.value=key!=='name'}}
function resetFilters(){search.value='';department.value='*';role.value=''}
function selectDepartment(value:string|number){department.value=String(value)}
function selectRole(value:string|number){role.value=String(value)}
watch(month,()=>{resetFilters();void load()})
watch(dimension,resetFilters)
watch(()=>[workspace.currentUser?.id,workspace.session?.tenant.id,identityConflict.value],()=>{invalidate();if(!identityConflict.value&&workspace.currentUser)void load()})
onMounted(()=>{void load();window.addEventListener('devflow-identity-changed',invalidate);window.addEventListener('devflow-auth-expired',invalidate)})
onBeforeUnmount(()=>{disposed=true;invalidate();window.removeEventListener('devflow-identity-changed',invalidate);window.removeEventListener('devflow-auth-expired',invalidate)})
</script>

<template>
  <div class="workload-page">
    <header class="workload-heading compact-page-heading"><div><h1>{{t('月度工作量')}}</h1><details class="page-heading-note"><summary :aria-label="t('页面说明')" :title="t('页面说明')"><span aria-hidden="true">?</span></summary><p>{{t('以需求权重观察团队贡献，按人员、部门和职能统一汇总。')}}</p></details></div><Button variant="outline" :disabled="loading||identityConflict||!monthValid" @click="load"><Icon name="refresh" :size="15"/>{{t('刷新统计')}}</Button></header>
    <section class="workload-month"><div><span class="workload-month-icon" aria-hidden="true">▦</span><div><b>{{t('迭代归属月份')}}</b><small>{{t('按迭代结束日期归月，不按需求创建时间')}}</small></div></div><div class="workload-month-controls"><Button variant="ghost" size="icon-sm" :aria-label="t('上个月')" :disabled="identityConflict||moveWorkloadMonth(month,-1)===month" @click="month=moveWorkloadMonth(month,-1)">‹</Button><DatePicker v-model="month" mode="month" required @validity-change="setMonthValidity" min="0001-01" max="9998-12" :label="t('选择统计月份')" :disabled="identityConflict"/><Button variant="ghost" size="icon-sm" :aria-label="t('下个月')" :disabled="identityConflict||moveWorkloadMonth(month,1)===month" @click="month=moveWorkloadMonth(month,1)">›</Button><Button variant="outline" size="sm" :disabled="identityConflict||month===currentWorkloadMonth()" @click="month=currentWorkloadMonth()">{{t('本月')}}</Button></div></section>
    <p v-if="error" class="workload-error" role="alert">{{t(error)}}</p>
    <div v-if="forbidden&&!report" class="workload-empty"><Icon name="lock" :size="28"/><h2>{{t('工作量统计需要专门授权')}}</h2><p>{{t('仅企业管理员和拥有 reports.view 权限的用户可以查看公司范围统计。')}}</p></div>
    <div v-else-if="loading&&!report" class="workload-empty" role="status"><span class="spinner"></span>{{t('正在计算月度统计…')}}</div>
    <template v-if="report">
      <div class="workload-scope"><span><i></i>{{report.scope.tenantName}} · {{t('全公司范围')}} · {{t('{count} 个项目',{count:report.scope.projectCount})}} · {{t('{count} 个迭代',{count:report.sprintCount})}}</span><small>{{t('当前状态快照')}} · {{formatDate(report.generatedAt)}}</small></div>
      <section class="workload-cards"><article v-for="metric in metrics" :key="metric.key"><span>{{t(metric.name)}}</span><b>{{metric.key==='weight'?formatWeight(report.totals.weight):formatNumber(report.totals[metric.key])}}</b><small>{{t(metric.key==='weight'?'职能权重相加，不是工时':metric.key==='shippedRequirementCount'?'已完成类别且属于工作流结束状态':'公司范围按工作项 ID 去重')}}</small></article></section>
      <section v-if="hasGaps" class="workload-gaps" role="status"><strong>{{t('数据完整性提示')}}</strong><span v-if="report.unestimatedRequirementCount">{{t('{count} 条需求尚未填入任何权重',{count:report.unestimatedRequirementCount})}}</span><span v-if="report.unassignedWeight">{{t('未分配权重：{value}',{value:formatWeight(report.unassignedWeight)})}}</span><span v-if="report.unassignedRequirementCount">{{t('{count} 条需求未绑定职能成员',{count:report.unassignedRequirementCount})}}</span><span v-if="report.unassignedDefectCount">{{t('{count} 个缺陷缺少稳定处理人 ID',{count:report.unassignedDefectCount})}}</span><span v-if="report.ambiguousSprintItemCount">{{t('{count} 个历史工作项的迭代简称有歧义，未计入',{count:report.ambiguousSprintItemCount})}}</span></section>
      <WorkloadTrends :month="month" :refresh-key="trendRefresh" :disabled="identityConflict||!monthValid"/>
      <section class="workload-detail"><div class="workload-toolbar"><div class="workload-tabs" role="tablist" :aria-label="t('统计维度')"><button v-for="item in dimensions" :key="item.key" type="button" role="tab" :aria-selected="dimension===item.key" :class="{active:dimension===item.key}" @click="dimension=item.key">{{t(item.name)}}<small>{{item.key==='people'?report.people.length:item.key==='departments'?report.departments.length:report.roles.length}}</small></button></div><div class="workload-filters"><input v-model="search" :aria-label="t('搜索统计明细')" :placeholder="t('搜索姓名、部门或职能')"/><AppSelect v-if="dimension==='people'" class="workload-filter-select" :model-value="department" :options="departmentOptions" :label="t('筛选所属部门')" @update:model-value="selectDepartment"/><AppSelect v-if="dimension==='people'" class="workload-filter-select" :model-value="role" :options="roleOptions" :label="t('筛选职能')" @update:model-value="selectRole"/></div></div>
        <ScrollArea class="workload-table-scroll" horizontal><table class="workload-table"><thead><tr><th class="workload-rank">{{t('序号')}}</th><th :aria-sort="sort==='name'?(descending?'descending':'ascending'):'none'"><button type="button" @click="changeSort('name')">{{t(dimension==='people'?'成员':dimension==='departments'?'部门':'职能')}} <span>{{sort==='name'?(descending?'↓':'↑'):'↕'}}</span></button></th><th v-if="dimension==='people'">{{t('所属部门 / 职能')}}</th><th v-if="dimension==='departments'">{{t('参与成员')}}</th><th v-for="metric in metrics" :key="metric.key" :aria-sort="sort===metric.key?(descending?'descending':'ascending'):'none'"><button type="button" @click="changeSort(metric.key)">{{t(metric.name)}} <span>{{sort===metric.key?(descending?'↓':'↑'):'↕'}}</span></button></th><th>{{t('未估算职能项')}}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td class="workload-rank">{{index+1}}</td><td><div class="workload-person"><span class="workload-avatar" :class="{inactive:row.active===false}">{{row.name.slice(0,1)}}</span><div><b>{{row.name}}</b><small v-if="row.active===false">{{t('历史停用成员')}}</small></div></div></td><td v-if="dimension==='people'"><div class="workload-person-meta"><span>{{row.departmentName||t('未分配部门')}}</span><small>{{(row.roleKeys||[]).map(key=>t(workloadRoleNames[key]||key)).join(' · ')}}</small></div></td><td v-if="dimension==='departments'">{{row.memberCount}}</td><td class="workload-weight">{{formatWeight(row.weight)}}<small v-if="row.unestimatedRoleCount&&row.estimatedRoleCount===0">{{t('尚未估算')}}</small></td><td>{{formatNumber(row.requirementCount)}}</td><td><span class="workload-shipped">{{formatNumber(row.shippedRequirementCount)}}</span></td><td>{{formatNumber(row.defectCount)}}</td><td><span :class="{'workload-missing':row.unestimatedRoleCount>0}">{{formatNumber(row.unestimatedRoleCount)}}</span></td></tr></tbody></table><div v-if="!rows.length" class="workload-empty"><h2>{{t('暂无匹配的统计记录')}}</h2><p>{{t('仅显示本月迭代需求职能或缺陷的实际参与者，不生成虚假的零工作量成员。')}}</p><Button v-if="search||department!=='*'||role" variant="outline" @click="resetFilters">{{t('清除筛选')}}</Button></div></ScrollArea>
        <footer class="workload-detail-footer"><span>{{t('{count} 条明细',{count:rows.length})}}</span><span>{{t('筛选仅影响明细；顶部总览始终为公司全量。')}}<template v-if="dimension==='people'&&role"> {{t('已按所选职能展示个人指标。')}}</template></span></footer>
      </section>
      <details class="workload-definitions"><summary>{{t('统计口径与使用说明')}}</summary><ul><li>{{t('月份采用 UTC 日历日期的迭代结束日；待规划、无结束日期及其他月份迭代不计入。')}}</li><li>{{t('每条需求的前端、后端、算法、UI、产品权重独立计入；同职能绑定多人时等分该项权重，汇总后保留六位小数。')}}</li><li>{{t('个人需求与上线数按五职能绑定成员归属。部门按当前有效主部门归属，无主部门时取排序首个有效关系；无关系单列。')}}</li><li>{{t('已上线包含 category=done 且配置为工作流结束状态的需求；统计使用当前状态，不代表该月实际发布事件。')}}</li><li>{{t('缺陷按自身迭代归月、稳定处理人 ID 归人、缺陷职能归类；不按姓名推断处理人，不代表个人缺陷责任。')}}</li><li>{{t('公司、部门和职能数量分别按工作项 ID 去重；一条需求可涉及多个部门或职能，因此分组数量不能直接相加。')}}</li><li>{{t('这是当前数据与组织关系的快照。仅用于协作计划，不应单独作为绩效或薪酬依据。')}}</li></ul></details>
    </template>
  </div>
</template>

<style scoped>
.workload-page{padding:28px 32px 44px;max-width:1800px;margin:auto;color:var(--ink);background:var(--surface-subtle)}.workload-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.workload-eyebrow{font-size:11px;color:var(--muted);letter-spacing:.06em}.workload-heading h1{font-size:24px;letter-spacing:-.03em;margin:9px 0}.workload-heading p{margin:0;color:var(--muted);font-size:12px}.workload-month{padding:18px 22px;background:var(--surface);border:1px solid var(--line);border-radius:12px;display:flex;justify-content:space-between;align-items:center;gap:16px}.workload-month>div:first-child{display:flex;align-items:center;gap:13px}.workload-month-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:10px;background:var(--primary-soft);color:var(--primary);font-size:25px}.workload-month b{font-size:13px}.workload-month small{display:block;font-size:11px;color:var(--muted);margin-top:4px}.workload-month-controls{display:flex;align-items:center;gap:8px}.workload-month input{border:1px solid var(--line);border-radius:7px;padding:7px 10px;background:var(--surface);color:var(--ink);font-size:13px}.workload-scope{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:18px 0 12px;font-size:11px;color:var(--muted)}.workload-scope i{display:inline-block;width:6px;height:6px;background:var(--success);border-radius:50%;margin-right:6px}.workload-scope small{font-size:10px}.workload-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.workload-cards article{padding:20px 22px;border:1px solid var(--line);border-radius:11px;background:var(--surface);display:grid;gap:9px}.workload-cards span{font-size:12px;color:var(--muted)}.workload-cards b{font-size:30px;line-height:1.2;font-variant-numeric:tabular-nums;font-weight:650;letter-spacing:-.035em}.workload-cards article:first-child b{color:var(--primary)}.workload-cards small{font-size:10px;color:var(--muted);line-height:1.5}.workload-gaps{display:flex;flex-wrap:wrap;gap:8px 18px;margin:16px 0 0;padding:12px 16px;background:var(--warning-background);border:1px solid var(--warning-border);border-radius:9px;color:var(--warning);font-size:11px;line-height:1.6}.workload-detail{margin-top:22px;background:var(--surface);border:1px solid var(--line);border-radius:11px;overflow:visible}.workload-toolbar{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:14px;padding:15px 18px;border-bottom:1px solid var(--line);border-radius:11px 11px 0 0}.workload-tabs{display:flex;gap:4px}.workload-tabs button{border:0;border-radius:7px;background:transparent;color:var(--muted);font-size:12px;padding:8px 10px;cursor:pointer;white-space:nowrap}.workload-tabs button.active{background:var(--primary-soft);color:var(--primary);font-weight:600}.workload-tabs small{margin-left:7px;opacity:.7;font-size:10px}.workload-filters{display:flex;flex-wrap:wrap;gap:8px}.workload-filters input,.workload-filters :deep(.workload-filter-select){border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink);padding:7px 9px;font-size:11px;max-width:190px}.workload-filters :deep(.workload-filter-select){min-width:150px}.workload-table-scroll{max-height:600px;height:clamp(260px,45vh,600px);border-radius:0 0 11px 11px}.workload-table{width:100%;min-width:920px;border-collapse:collapse;text-align:left;font-size:12px}.workload-table th{position:sticky;top:0;z-index:1;background:var(--surface-subtle);font-size:11px;font-weight:500;color:var(--muted);height:45px;white-space:nowrap}.workload-table th,.workload-table td{padding:12px 14px;border-bottom:1px solid var(--line)}.workload-table th button{background:none;border:0;padding:0;color:inherit;font:inherit;cursor:pointer;display:inline-flex;gap:8px;align-items:center}.workload-table th button span{font-size:10px;opacity:.65}.workload-table tbody tr:hover{background:var(--surface-subtle)}.workload-table td{font-variant-numeric:tabular-nums}.workload-rank{width:48px;text-align:center!important;color:var(--muted)}.workload-person{display:flex;align-items:center;gap:10px}.workload-avatar{display:grid;place-items:center;width:31px;height:31px;border-radius:9px;background:var(--primary-soft);color:var(--primary);font-size:12px;flex:none}.workload-avatar.inactive{filter:grayscale(1);opacity:.7}.workload-person b{font-size:12px;font-weight:550}.workload-person small,.workload-person-meta small{display:block;font-size:10px;color:var(--muted);margin-top:5px}.workload-person-meta span{font-size:11px}.workload-weight{font-weight:600;color:var(--primary)}.workload-weight small{display:block;font-weight:400;font-size:10px;color:var(--muted);margin-top:4px}.workload-shipped{display:inline-flex;align-items:center;justify-content:center;min-width:24px;padding:3px 5px;border-radius:5px;background:var(--success-background);color:var(--success);font-size:11px}.workload-missing{color:var(--warning)}.workload-detail-footer{display:flex;justify-content:space-between;gap:12px;padding:12px 18px;color:var(--muted);font-size:10px;border-top:1px solid var(--line);border-radius:0 0 11px 11px}.workload-definitions{padding:16px 2px;color:var(--muted);font-size:11px;line-height:1.9}.workload-definitions summary{cursor:pointer;color:var(--ink);font-weight:550}.workload-definitions ul{padding-left:20px;max-width:1200px}.workload-error{background:var(--danger-background);border:1px solid var(--danger-border);color:var(--danger);border-radius:8px;padding:12px 16px;font-size:12px}.workload-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:13px;padding:50px 24px;text-align:center;color:var(--muted);font-size:12px}.workload-empty h2{font-size:15px;font-weight:550;margin:0;color:var(--ink)}.workload-empty p{margin:0;max-width:620px;line-height:1.8}@media(max-width:1050px){.workload-page{padding:20px}.workload-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.workload-heading,.workload-month,.workload-scope{align-items:flex-start}.workload-scope{flex-direction:column}}@media(max-width:650px){.workload-heading,.workload-month{flex-direction:column}.workload-page{padding:16px}.workload-cards article{padding:15px}.workload-cards b{font-size:24px}.workload-detail-footer{flex-direction:column}.workload-tabs button{padding:8px}.workload-filters input{max-width:100%}}
</style>

